(() => {
'use strict';
const root=document.getElementById('rmd-app');
const $=id=>root.querySelector('#rmd-'+id);
// IRS Publication 590-B, Appendix B, Table III: ages 72 through 120+.
const factors=[27.4,26.5,25.5,24.6,23.7,22.9,22,21.1,20.2,19.4,18.5,17.7,16.8,16,15.2,14.4,13.7,12.9,12.2,11.5,10.8,10.1,9.5,8.9,8.4,7.8,7.3,6.8,6.4,6,5.6,5.2,4.9,4.6,4.3,4.1,3.9,3.7,3.5,3.4,3.3,3.1,3,2.9,2.8,2.7,2.5,2.3,2];
const currency=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'});
const money=cents=>currency.format(cents/100);
const put=(id,text)=>{$(id).textContent=text;};
let validResult=false;
let reportSnapshot=null;
function cents(text,label){
 const s=text.trim();
 if(!/^(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d{1,2})?$/.test(s))throw Error(label+': enter a non-negative USD amount with up to 2 decimal places.');
 const [whole,frac='']=s.replaceAll(',','').split('.');
 const n=Number(whole)*100+Number(frac.padEnd(2,'0'));
 if(!Number.isSafeInteger(n)||n>100000000000)throw Error(label+': maximum supported amount is $1 billion.');
 return n;
}
function birth(value){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(value))throw Error('Enter a valid date of birth.');
 const [y,m,d]=value.split('-').map(Number),dt=new Date(Date.UTC(y,m-1,d));
 if(y<1900||dt.getUTCFullYear()!==y||dt.getUTCMonth()!==m-1||dt.getUTCDate()!==d)throw Error('Enter a valid date of birth from 1900 onward.');
 return {y,m,d};
}
function startYear(b){
 if(b.y<1949||(b.y===1949&&b.m<7))return b.y+(b.m>6?71:70);
 return b.y+(b.y<=1950?72:b.y<=1959?73:75);
}
function compute(v){
 if(!Number.isInteger(v.year)||v.year<2026||v.year>2060)throw Error('Choose a distribution year from 2026 to 2060.');
 const b=birth(v.dob),age=v.year-b.y;
 if(age<0||age>130||v.dob>new Date().toISOString().slice(0,10))throw Error('Check your birth date. Age in the distribution year must be 0–130 and the birth date cannot be in the future.');
 if(v.type==='inherited')throw Error('Inherited accounts need beneficiary-specific rules. This calculator cannot determine their RMD. Ask your custodian for an inherited-account calculation.');
 if(v.type==='plan'&&v.plan!=='standard')throw Error('This calculator supports standard age-based plan RMDs only. Confirm the retirement exception and first distribution year with your plan administrator.');
 const first=startYear(b),exempt=v.type==='roth',required=!exempt&&v.year>=first;
 if(required&&v.spouse==='yes')throw Error('Use IRS Table II (Joint and Last Survivor) for a sole-beneficiary spouse more than 10 years younger. The Uniform Lifetime result would be incorrect.');
 const factor=required?factors[Math.min(age,120)-72]:null;
 if(required&&!factor)throw Error('No supported IRS factor for this age.');
 // Integer arithmetic: cents * 10 / factor-tenths. Round annual RMD upward.
 const divisor=factor?Math.round(factor*10):null;
 const annual=required?Math.floor((v.balance*10+divisor-1)/divisor):0;
 return {age,first,exempt,required,factor,annual,remaining:Math.max(0,annual-v.taken),firstYear:required&&v.year===first,birthYear:b.y};
}
function table(age){$('table').innerHTML=factors.map((f,i)=>'<tr'+(Math.min(age,120)===i+72?' class="rmd-selected"':'')+'><td>'+(i===48?'120+':i+72)+'</td><td>'+f.toFixed(1)+'</td><td>'+(100/f).toFixed(2)+'%</td></tr>').join('');}
function sync(){const y=Number($('year').value);put('balance-date',Number.isInteger(y)&&y>=2026&&y<=2060?'December 31, '+(y-1):'the previous December 31');$('plan-row').hidden=$('type').value!=='plan';$('spouse-row').hidden=['roth','inherited'].includes($('type').value);}
function clearResults(message){
 validResult=false;$('pdf').disabled=true;
 ['annual','monthly','rate','paid','remaining','age','factor','deadline'].forEach(id=>put(id,'—'));
 put('status','Calculation unavailable');put('equation','Review the message below your inputs.');put('note',message);put('progress-text','No result available.');$('bar').style.width='0%';$('progress').setAttribute('aria-valuenow','0');table(-1);
}
function calculate(example=false){
 sync();$('error').hidden=true;$('stale').hidden=true;
 try{
 const v={year:Number($('year').value),dob:$('dob').value,type:$('type').value,plan:$('plan').value,spouse:$('spouse').value,balance:cents($('balance').value,'Account balance'),taken:cents($('taken').value,'Withdrawals')};
 const r=compute(v),pc=r.annual?Math.min(100,100*v.taken/r.annual):0;
 put('annual',money(r.annual));put('monthly',money(Math.round(r.annual/12)));put('rate',r.required?(100/r.factor).toFixed(2)+'%':'0.00%');
 put('status',example?'Example · '+v.year:r.exempt?'No lifetime RMD':!r.required?'RMDs have not started':r.remaining===0?'RMD requirement met':r.firstYear?'Your first RMD year':v.year+' distribution');
 put('equation',r.required?money(v.balance)+' ÷ '+r.factor.toFixed(1)+' IRS factor · rounded up':r.exempt?'Original-owner Roth account':'First age-based RMD year: '+r.first);
 put('paid',money(v.taken));put('remaining',money(r.remaining));put('age',r.age+' years');put('factor',r.factor?r.factor.toFixed(1):'Not applicable');
 put('deadline',!r.required?'No RMD due for '+v.year:r.firstYear?'April 1, '+(v.year+1):'December 31, '+v.year);
 $('bar').style.width=pc+'%';$('progress').setAttribute('aria-valuenow',pc.toFixed(1));
 put('progress-text',r.annual?pc.toFixed(1)+'% of your annual RMD covered'+(v.taken>r.annual?' · Excess cannot offset next year’s RMD.':'.'):'No required withdrawal based on these inputs.');
 let note=r.exempt?'Original owners have no lifetime RMDs for these Roth accounts. Beneficiary rules are different.':!r.required?'Your first age-based RMD year is '+r.first+'. Recalculate then using the balance from the preceding December 31.':r.firstYear?'You may take this RMD during '+v.year+' or by April 1, '+(v.year+1)+'. Delaying does not move the December 31, '+(v.year+1)+' deadline for the following year’s separate RMD.':'Use qualifying distributions credited to '+v.year+' to meet this amount by December 31. A prior year’s delayed first RMD is a separate requirement.';
 if(r.birthYear===1959&&!r.exempt)note+=' Birth year 1959 uses age 73 under the IRS proposed clarification; confirm final guidance with your custodian.';
 if(v.year>new Date().getFullYear())note+=' Future-year estimate: assumes unchanged laws and tables.';
 put('note',note);table(r.age);reportSnapshot={v,r,note,deadline:$('deadline').textContent};validResult=true;$('pdf').disabled=false;
 }catch(e){put('error',e.message);$('error').hidden=false;clearResults(e.message);}
}
$('form').addEventListener('submit',e=>{e.preventDefault();calculate();});
function changed(){sync();validResult=false;$('pdf').disabled=true;$('stale').hidden=false;}
$('form').addEventListener('input',changed);$('form').addEventListener('change',changed);
$('reset').addEventListener('click',()=>{$('form').reset();calculate(true);});

function buildPdf(report){
 const {v,r,note,deadline}=report;
 const clean=s=>String(s).replace(/[–—]/g,'-').replace(/½/g,'1/2').replace(/[’‘]/g,"'").replace(/[“”]/g,'"').replace(/[^\x20-\x7e]/g,' ');
 const escape=s=>clean(s).replace(/([\\()])/g,'\\$1');
 const ink='0.063 0.165 0.298',blue='0.145 0.388 0.922',muted='0.349 0.420 0.510';
 const commands=[];
 const rect=(x,y,w,h,color)=>commands.push(`${color} rg ${x} ${842-y-h} ${w} ${h} re f`);
 const text=(s,x,y,size=11,bold=false,color=ink)=>commands.push(`BT /${bold?'F2':'F1'} ${size} Tf ${color} rg 1 0 0 1 ${x} ${842-y} Tm (${escape(s)}) Tj ET`);
 function wrap(s,max=83){const lines=[];let line='';for(const word of clean(s).split(/\s+/)){if((line+' '+word).trim().length>max&&line){lines.push(line);line=word;}else line=(line+' '+word).trim();}if(line)lines.push(line);return lines;}
 rect(0,0,595,112,ink);text('EasyCalculator',36,34,12,true,'1 1 1');text('Required Minimum Distribution',36,65,22,true,'1 1 1');text(`Retirement withdrawal report | ${v.year} | USD`,36,89,11,false,'0.83 0.9 1');
 rect(36,130,523,91,'0.93 0.96 1');text('ESTIMATED ANNUAL RMD',52,154,10,true,muted);text(money(r.annual),52,192,31,true,blue);
 text(r.required?`Year-end balance / ${r.factor.toFixed(1)} IRS factor; annual amount rounded upward to the next cent.`:r.exempt?'No lifetime RMD for the original owner of this Roth account.':`No RMD due for ${v.year}. First age-based RMD year: ${r.first}.`,36,242,10,false,muted);
 text('ACCOUNT & RESULTS',36,272,11,true,blue);
 const account={ira:'Traditional / SEP / SIMPLE IRA',plan:'Pre-tax employer plan - standard age-based rules',roth:'Original-owner Roth account'};
 const rows=[['Distribution year',v.year],['Account type',account[v.type]],['Age on December 31',r.age+' years'],[`Balance on December 31, ${v.year-1}`,money(v.balance)],['IRS Uniform Lifetime factor',r.factor?r.factor.toFixed(1):'Not applicable'],['Credited withdrawals',money(v.taken)],['Still to withdraw',money(r.remaining)],['Monthly equivalent (not a deadline)',money(Math.round(r.annual/12))],['Withdrawal rate',r.required?(100/r.factor).toFixed(2)+'%':'0.00%'],['Withdrawal deadline',deadline]];
 let y=292;rows.forEach(([label,value],i)=>{if(i%2===0)rect(36,y-13,523,25,'0.963 0.973 0.985');text(label,46,y+3,10,false,muted);text(value,296,y+3,9,true);y+=25;});
 text('DEADLINE & PLANNING NOTES',36,569,11,true,blue);
 let ny=590;for(const line of wrap(note,94)){text(line,36,ny,10);ny+=14;}
 const caution='Educational estimate, not personalized tax advice. Confirm your requirement with your custodian. Monthly values are planning equivalents. Excess distributions cannot offset next year\'s RMD. Future-year results assume unchanged rules.';
 ny+=13;for(const line of wrap(caution,98)){text(line,36,ny,9,false,muted);ny+=12;}
 text('Source: IRS Publication 590-B, Appendix B, Table III; IRS RMD FAQs.',36,781,9,false,muted);
 text('easycalculator.org/rmd-calculator',36,800,9,true,blue);text('Page 1 of 1',497,800,9,false,muted);
 const stream=commands.join('\n');
 const regularFont=atob(''),boldFont=atob('');
 const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>','<< /Type /Font /Subtype /TrueType /BaseFont /ECRMDRegular /Encoding /WinAnsiEncoding /FirstChar 32 /LastChar 126 /Widths [318 401 460 838 636 950 780 275 390 390 500 838 318 361 318 337 636 636 636 636 636 636 636 636 636 636 337 337 838 838 838 531 1000 684 686 698 770 632 575 775 752 295 295 656 557 863 748 787 603 787 695 635 611 732 684 989 685 611 685 390 337 390 838 500 500 613 635 550 635 615 352 635 634 278 278 579 278 974 634 612 635 635 411 521 392 634 592 818 592 592 525 636 337 636 838] /FontDescriptor 7 0 R >>','<< /Type /Font /Subtype /TrueType /BaseFont /ECRMDBold /Encoding /WinAnsiEncoding /FirstChar 32 /LastChar 126 /Widths [348 456 521 838 696 1002 872 306 457 457 523 838 380 415 380 365 696 696 696 696 696 696 696 696 696 696 400 400 838 838 838 580 1000 774 762 734 830 683 683 821 837 372 372 775 637 995 837 850 733 850 770 720 682 812 774 1103 771 724 725 457 365 457 838 500 500 675 716 593 716 678 435 716 712 343 343 665 343 1042 712 687 716 716 493 595 478 712 652 924 645 652 582 712 365 712 838] /FontDescriptor 8 0 R >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,'<< /Type /FontDescriptor /FontName /ECRMDRegular /Flags 32 /FontBBox [-52 -261 956 946] /ItalicAngle 0 /Ascent 928 /Descent -236 /CapHeight 730 /StemV 80 /FontFile2 9 0 R >>','<< /Type /FontDescriptor /FontName /ECRMDBold /Flags 32 /FontBBox [-56 -236 1072 800] /ItalicAngle 0 /Ascent 928 /Descent -236 /CapHeight 730 /StemV 80 /FontFile2 10 0 R >>',`<< /Length ${regularFont.length} /Length1 ${regularFont.length} >>\nstream\n${regularFont}\nendstream`,`<< /Length ${boldFont.length} /Length1 ${boldFont.length} >>\nstream\n${boldFont}\nendstream`];
 let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((obj,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${obj}\nendobj\n`;});
 const xref=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;for(const n of offsets.slice(1))pdf+=`${String(n).padStart(10,'0')} 00000 n \n`;
 pdf+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
 return new Blob([Uint8Array.from(pdf,c=>c.charCodeAt(0))],{type:'application/pdf'});
}
$('pdf').addEventListener('click',()=>{
 if(!validResult||!reportSnapshot)return;
 const button=$('pdf');button.disabled=true;
 try{
  const blob=buildPdf(reportSnapshot),url=URL.createObjectURL(blob),link=document.createElement('a');
  link.href=url;link.download=`EasyCalculator-RMD-${reportSnapshot.v.year}.pdf`;document.body.appendChild(link);link.click();link.remove();
  setTimeout(()=>URL.revokeObjectURL(url),60000);
 }catch(error){put('error','Could not download the PDF. Please try again in an updated browser.');$('error').hidden=false;}
 finally{button.disabled=!validResult;}
});
calculate(true);
})();